INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
  ('b0000000-0000-0000-0016-000000000000', 'CI/CD란 무엇이며 왜 중요한가요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000001', 'Continuous Integration, Delivery, Deployment의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000002', 'CI를 구현하면 얻는 주요 이점은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000003', '빌드 파이프라인(Build Pipeline)이란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000004', 'CI/CD 파이프라인의 주요 단계를 설명해 주세요 (예: 빌드, 테스트, 배포).', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000005', '버전 관리 시스템(예: Git)을 CI/CD에서 어떻게 활용하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000006', 'Jenkins는 무엇이며 어떤 역할을 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000007', 'Jenkins의 파이프라인(Pipeline) 기능은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000008', 'Jenkins Scripted 파이프라인과 Declarative 파이프라인의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000009', 'GitLab CI/CD나 GitHub Actions를 사용해본 경험이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000A', 'CI 도구(예: Jenkins, CircleCI, Travis CI)를 선택할 때 고려사항은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000B', 'CI/CD 도입 시 나타날 수 있는 도전과제(challenges)는 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000C', '배포 자동화(Deployment Automation)를 위해 어떤 전략이나 도구를 사용해봤나요?', 'HARD', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000D', '롤백(Rollback) 전략은 CI/CD에서 왜 중요하며 어떻게 구현하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000E', 'CI 파이프라인에서 테스트 자동화는 어떻게 구성하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-00000000000F', 'CD 파이프라인에서 Canary 배포와 Blue-Green 배포는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000010', 'Infrastructure as Code(IaC)는 무엇이며 CI/CD에서 어떻게 활용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000011', 'CI/CD 환경에서 보안(예: 시크릿 관리)은 어떻게 구현하고 있나요?', 'HARD', 'b0000000-0000-0000-0000-000000000016'),
  ('b0000000-0000-0000-0016-000000000012', '모놀리틱(Monolithic) 아키텍처와 마이크로서비스(Microservices) 아키텍처에서 CI/CD의 차이는?', 'HARD', 'b0000000-0000-0000-0000-000000000016');
